.sc-tw :root{
            --sunlight-cream: oklch(97% 0.02 90);
            --sun-linen: oklch(92% 0.03 85);
            --chlorophyll: oklch(45% 0.12 140);
            --chlorophyll-light: oklch(65% 0.10 140);
            --oak-brown: oklch(50% 0.08 60);
            --deep-forest: oklch(25% 0.08 140);
            --warm-amber: oklch(75% 0.15 65);
        }.sc-tw{
            background-color: var(--sunlight-cream);
            color: var(--deep-forest);
            font-family: 'Manrope', sans-serif;
            margin: 0;
            overflow-x: hidden;
            scroll-behavior: smooth;
        }.sc-tw h1,.sc-tw h2,.sc-tw h3,.sc-tw h4,.sc-tw .serif{ font-family: 'Cormorant Garamond', serif; }.sc-tw .hero-wrapper{
            position: relative;
            width: 100vw;
            height: 100vh;
            overflow: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
        }.sc-tw .video-bg{
            position: absolute;
            top: 50%;
            left: 50%;
            min-width: 100%;
            min-height: 100%;
            width: auto;
            height: auto;
            transform: translate(-50%, -50%) scale(1.1);
            object-fit: cover;
            z-index: 0;
        }.sc-tw .hero-overlay{
            position: absolute;
            inset: 0;
            background: radial-gradient(circle at center, rgba(25, 40, 30, 0.2) 0%, rgba(25, 40, 30, 0.5) 100%);
            z-index: 1;
        }.sc-tw .glass-projection{
            background: rgba(255, 255, 255, 0.05);
            backdrop-filter: blur(40px) saturate(1.2);
            -webkit-backdrop-filter: blur(40px) saturate(1.2);
            border: 1px solid rgba(255, 255, 255, 0.1);
            box-shadow: 0 40px 100px rgba(0, 0, 0, 0.2);
            border-radius: 2rem;
        }.sc-tw .nav-link{
            position: relative;
            font-size: 0.8rem;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            transition: opacity 0.3s;
        }.sc-tw .nav-link::after{
            content: '';
            position: absolute;
            bottom: -4px;
            left: 0;
            width: 0;
            height: 1px;
            background: currentColor;
            transition: width 0.3s ease;
        }.sc-tw .nav-link:hover::after{ width: 100%; }.sc-tw .dew-drop{
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 1.25rem 3rem;
            border-radius: 50vw;
            background: var(--deep-forest);
            color: var(--sunlight-cream);
            font-weight: 500;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            transition: all 0.6s cubic-bezier(0.16, 1, 0.3, 1);
            cursor: pointer;
            border: none;
        }.sc-tw .dew-drop:hover{
            transform: translateY(-4px);
            background: var(--chlorophyll);
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.2);
        }.sc-tw .kinetic-letter{
            display: inline-block;
            animation: sway 7s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite alternate;
        }

        @keyframes sway {0%{ transform: rotate(-1deg) translateY(0); }100%{ transform: rotate(1deg) translateY(-2px); }
        }.sc-tw .bloom-element{
            opacity: 0;
            transform: translateY(30px);
            transition: all 1s ease-out;
        }.sc-tw .bloom-element.bloomed{
            opacity: 1;
            transform: translateY(0);
        }.sc-tw .furniture-card{
            background: white;
            padding: 1.5rem;
            border-radius: 0.5rem;
            transition: all 0.5s ease;
        }.sc-tw .furniture-card:hover{
            box-shadow: 0 30px 60px rgba(0, 0, 0, 0.05);
            transform: translateY(-10px);
